# Kaggle Research

First-party AERS integration for safe, reproducible access to datasets,
competitions, notebooks/kernels, and models through the official Kaggle CLI.

Open [`kaggle-research/SKILL.md`](kaggle-research/SKILL.md) for agent
instructions. Runtime code and tests are self-contained inside the skill
directory and use only the Python standard library. The integration provides:

- deny-by-default policy checks for remote writes and deletes;
- path-confined downloads with SHA-256 manifests;
- bounded, credential-redacted audit records;
- offline unit/contract tests and an opt-in real Kaggle read-only smoke test.

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import os
import shutil
import sys
from pathlib import Path
from typing import Optional, Sequence

from kaggle_runtime.artifacts import build_audit_record, write_audit
from kaggle_runtime.result import (
    CommandRequest,
    KaggleRuntimeError,
)
from kaggle_runtime.runner import KaggleRunner
from kaggle_runtime.security import redact_text
from kaggle_runtime.smoke import run_readonly_smoke


def _add_executable_options(parser: argparse.ArgumentParser) -> None:
    group = parser.add_mutually_exclusive_group()
    group.add_argument(
        "--python",
        type=Path,
        help="Python 3.11+ interpreter containing the kaggle package",
    )
    group.add_argument(
        "--executable",
        type=Path,
        help="Kaggle CLI executable",
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Safe, auditable wrapper around the official Kaggle CLI"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    doctor = subparsers.add_parser(
        "doctor",
        help="Check CLI version and authenticated read access",
    )
    _add_executable_options(doctor)
    doctor.add_argument("--json", action="store_true", dest="as_json")

    run = subparsers.add_parser(
        "run",
        help="Run an official Kaggle command through the safety boundary",
    )
    _add_executable_options(run)
    run.add_argument("--dry-run", action="store_true")
    run.add_argument("--allow-write", action="store_true")
    run.add_argument("--allow-delete", action="store_true")
    run.add_argument("--confirm-resource")
    run.add_argument("--output-root", type=Path)
    run.add_argument("--audit", type=Path)
    run.add_argument("--timeout", type=float, default=120.0)
    run.add_argument("kaggle_arguments", nargs=argparse.REMAINDER)

    smoke = subparsers.add_parser(
        "smoke-readonly",
        help="Run real read-only Kaggle verification",
    )
    _add_executable_options(smoke)
    smoke.add_argument("--output-root", type=Path, required=True)
    smoke.add_argument("--report", type=Path)
    smoke.add_argument(
        "--max-dataset-bytes",
        type=int,
        default=250_000,
    )
    return parser


def _strip_separator(arguments: Sequence[str]) -> tuple[str, ...]:
    values = tuple(arguments)
    if values and values[0] == "--":
        return values[1:]
    return values


def request_from_namespace(namespace: argparse.Namespace) -> CommandRequest:
    arguments = _strip_separator(namespace.kaggle_arguments)
    if not arguments:
        raise ValueError("run requires Kaggle arguments after --")
    return CommandRequest(
        arguments=arguments,
        output_root=namespace.output_root,
        timeout_seconds=namespace.timeout,
        allow_write=namespace.allow_write,
        allow_delete=namespace.allow_delete,
        confirm_resource=namespace.confirm_resource,
        dry_run=namespace.dry_run,
    )


def resolve_executable(
    *,
    python: Optional[Path] = None,
    executable: Optional[Path] = None,
) -> tuple[str, ...]:
    if python is not None and executable is not None:
        raise ValueError("--python and --executable are mutually exclusive")
    if python is not None:
        return (str(python), "-m", "kaggle")
    if executable is not None:
        return (str(executable),)

    environment_python = os.environ.get("AERS_KAGGLE_PYTHON")
    if environment_python:
        return (environment_python, "-m", "kaggle")
    environment_executable = os.environ.get("AERS_KAGGLE_EXECUTABLE")
    if environment_executable:
        return (environment_executable,)
    discovered = shutil.which("kaggle")
    if discovered:
        return (discovered,)
    return (sys.executable, "-m", "kaggle")


def build_doctor_commands() -> tuple[tuple[str, ...], ...]:
    return (
        ("--version",),
        ("datasets", "list", "-m", "-v"),
    )


def _runner(namespace: argparse.Namespace) -> KaggleRunner:
    return KaggleRunner(
        executable=resolve_executable(
            python=getattr(namespace, "python", None),
            executable=getattr(namespace, "executable", None),
        )
    )


def _doctor(namespace: argparse.Namespace) -> int:
    runner = _runner(namespace)
    records = []
    for command in build_doctor_commands():
        result = runner.execute(
            CommandRequest(arguments=command, retries=0)
        )
        records.append(build_audit_record(result, capture_limit=2048))
        if not result.ok:
            raise KaggleRuntimeError(
                result.error_category or "command",
                redact_text(result.stderr or result.stdout),
            )
    payload = {
        "status": "passed",
        "checks": {
            "cli_version": True,
            "authenticated_account_list": True,
        },
        "audits": records,
    }
    if namespace.as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print("Kaggle doctor passed: CLI available and account access authenticated.")
    return 0


def _run(namespace: argparse.Namespace) -> int:
    request = request_from_namespace(namespace)
    result = _runner(namespace).execute(request)
    record = build_audit_record(result, capture_limit=request.capture_limit)
    if namespace.audit is not None:
        write_audit(result, namespace.audit, capture_limit=request.capture_limit)
    print(json.dumps(record, ensure_ascii=False, indent=2))
    return 0 if result.ok else 1


def _smoke(namespace: argparse.Namespace) -> int:
    report = run_readonly_smoke(
        _runner(namespace),
        output_root=namespace.output_root,
        max_dataset_bytes=namespace.max_dataset_bytes,
        report_path=namespace.report,
    )
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = build_parser()
    namespace = parser.parse_args(argv)
    try:
        if namespace.command == "doctor":
            return _doctor(namespace)
        if namespace.command == "run":
            return _run(namespace)
        if namespace.command == "smoke-readonly":
            return _smoke(namespace)
        parser.error(f"unknown command: {namespace.command}")
    except (KaggleRuntimeError, ValueError) as exc:
        category = getattr(exc, "category", "usage")
        payload = {
            "status": "failed",
            "category": category,
            "message": redact_text(str(exc)),
        }
        print(
            json.dumps(payload, ensure_ascii=False, indent=2),
            file=sys.stderr,
        )
        return 2
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

from collections.abc import Sequence

from .result import CommandRequest, KaggleRuntimeError, OperationClass
from .security import contains_inline_credential


READ_ACTIONS = frozenset(
    {
        ("competitions", "files"),
        ("competitions", "leaderboard"),
        ("competitions", "list"),
        ("competitions", "submissions"),
        ("datasets", "files"),
        ("datasets", "list"),
        ("datasets", "status"),
        ("datasets", "view"),
        ("kernels", "files"),
        ("kernels", "list"),
        ("kernels", "logs"),
        ("kernels", "status"),
        ("models", "files"),
        ("models", "list"),
    }
)

DOWNLOAD_ACTIONS = frozenset(
    {
        ("competitions", "download"),
        ("competitions", "logs"),
        ("competitions", "replay"),
        ("datasets", "download"),
        ("datasets", "metadata"),
        ("kernels", "output"),
        ("kernels", "pull"),
    }
)

WRITE_ACTIONS = frozenset(
    {
        ("auth", "login"),
        ("auth", "revoke"),
        ("competitions", "submit"),
        ("datasets", "create"),
        ("datasets", "init"),
        ("datasets", "version"),
        ("kernels", "init"),
        ("kernels", "push"),
        ("models", "create"),
        ("models", "init"),
        ("models", "update"),
    }
)

DELETE_GROUPS = frozenset(
    {"competitions", "datasets", "kernels", "models"}
)

GROUP_ALIASES = {
    "c": "competitions",
    "d": "datasets",
    "k": "kernels",
    "m": "models",
}

READ_PREFIXES = (
    ("competitions", "team-submissions"),
    ("competitions", "episodes"),
    ("competitions", "pages"),
    ("competitions", "topics"),
    ("competitions", "topic-messages"),
    ("datasets", "topics"),
    ("kernels", "topics"),
    ("models", "topics"),
    ("models", "instances", "files"),
    ("models", "instances", "list"),
    ("models", "instances", "versions", "files"),
    ("models", "instances", "versions", "list"),
)

DOWNLOAD_PREFIXES = (
    ("models", "instances", "versions", "download"),
)

WRITE_PREFIXES = (
    ("models", "instances", "init"),
    ("models", "instances", "create"),
    ("models", "instances", "update"),
    ("models", "instances", "versions", "create"),
)

DELETE_PREFIXES = (
    ("models", "instances", "delete"),
    ("models", "instances", "versions", "delete"),
)

SENSITIVE_COMMANDS = frozenset({("auth", "print-access-token")})

RESOURCE_FLAGS = frozenset(
    {
        "-c",
        "--competition",
        "-d",
        "--dataset",
        "-k",
        "--kernel",
        "--model",
        "--model-variation",
    }
)


def _group_action(arguments: Sequence[str]) -> tuple[str, str]:
    normalized = _normalized_arguments(arguments)
    if not normalized:
        return "", ""
    group = normalized[0]
    if group == "--version":
        return group, ""
    action = normalized[1] if len(normalized) > 1 else ""
    return group, action


def _normalized_arguments(arguments: Sequence[str]) -> tuple[str, ...]:
    values = tuple(str(argument).strip().lower() for argument in arguments)
    if not values:
        return values
    normalized = list(values)
    normalized[0] = GROUP_ALIASES.get(normalized[0], normalized[0])
    if len(normalized) > 1 and normalized[0] == "models":
        if normalized[1] in {"i", "variations", "v"}:
            normalized[1] = "instances"
        if (
            len(normalized) > 2
            and normalized[1] == "instances"
            and normalized[2] == "v"
        ):
            normalized[2] = "versions"
    return tuple(normalized)


def _starts_with(
    arguments: Sequence[str],
    prefix: tuple[str, ...],
) -> bool:
    return tuple(arguments[: len(prefix)]) == prefix


def _has_path_option(arguments: Sequence[str]) -> bool:
    return any(
        argument in {"-p", "--path"}
        or argument.startswith("-p=")
        or argument.startswith("--path=")
        for argument in arguments
    )


def classify(arguments: Sequence[str]) -> OperationClass:
    normalized = _normalized_arguments(arguments)
    group, action = _group_action(normalized)
    if group == "--version":
        return OperationClass.READ
    if any(_starts_with(normalized, prefix) for prefix in DELETE_PREFIXES):
        return OperationClass.REMOTE_DELETE
    if any(_starts_with(normalized, prefix) for prefix in DOWNLOAD_PREFIXES):
        return OperationClass.DOWNLOAD
    if any(_starts_with(normalized, prefix) for prefix in WRITE_PREFIXES):
        return OperationClass.REMOTE_WRITE
    if any(_starts_with(normalized, prefix) for prefix in READ_PREFIXES):
        return OperationClass.READ
    if (
        _starts_with(normalized, ("competitions", "leaderboard"))
        and any(option in normalized for option in {"-d", "--download"})
    ):
        return OperationClass.DOWNLOAD
    if _starts_with(normalized, ("competitions", "leaderboard")):
        return OperationClass.READ
    if _starts_with(normalized, ("models", "get")):
        return (
            OperationClass.DOWNLOAD
            if _has_path_option(normalized)
            else OperationClass.READ
        )
    if _starts_with(normalized, ("models", "instances", "get")):
        return (
            OperationClass.DOWNLOAD
            if _has_path_option(normalized)
            else OperationClass.READ
        )
    if (group, action) in DOWNLOAD_ACTIONS:
        return OperationClass.DOWNLOAD
    if action == "delete" and group in DELETE_GROUPS:
        return OperationClass.REMOTE_DELETE
    if (group, action) in WRITE_ACTIONS:
        return OperationClass.REMOTE_WRITE
    if (group, action) in READ_ACTIONS:
        return OperationClass.READ
    if group == "config" and action in {"view", "get"}:
        return OperationClass.READ
    if group == "config" and action == "set":
        return OperationClass.REMOTE_WRITE
    return OperationClass.UNKNOWN


def _contains_control_characters(value: str) -> bool:
    return any(ord(character) < 32 or ord(character) == 127 for character in value)


def _extract_delete_resource(arguments: Sequence[str]) -> str | None:
    for index, argument in enumerate(arguments):
        if argument in RESOURCE_FLAGS and index + 1 < len(arguments):
            return str(arguments[index + 1])
        for flag in RESOURCE_FLAGS:
            prefix = f"{flag}="
            if str(argument).startswith(prefix):
                return str(argument)[len(prefix) :]

    normalized = _normalized_arguments(arguments)
    if "delete" in normalized:
        delete_index = normalized.index("delete")
        for argument in arguments[delete_index + 1 :]:
            value = str(argument)
            if not value.startswith("-"):
                return value
    return None


def authorize(request: CommandRequest) -> OperationClass:
    if not request.arguments:
        raise KaggleRuntimeError("policy", "Kaggle arguments cannot be empty")
    if any(_contains_control_characters(argument) for argument in request.arguments):
        raise KaggleRuntimeError(
            "policy",
            "Kaggle arguments cannot contain control characters",
        )
    if contains_inline_credential(request.arguments):
        raise KaggleRuntimeError(
            "policy",
            "Credentials must be provided through official Kaggle authentication",
        )

    group_action = _group_action(request.arguments)
    if group_action in SENSITIVE_COMMANDS:
        raise KaggleRuntimeError(
            "policy",
            "Printing access tokens is blocked by the Kaggle research runtime",
        )

    operation = classify(request.arguments)
    if operation is OperationClass.DOWNLOAD and request.output_root is None:
        raise KaggleRuntimeError(
            "policy",
            "Download operations require an explicit output root",
        )
    if operation in {OperationClass.REMOTE_WRITE, OperationClass.UNKNOWN}:
        if not request.allow_write:
            raise KaggleRuntimeError(
                "policy",
                f"{operation.value} operation requires --allow-write",
            )
    if operation is OperationClass.REMOTE_DELETE:
        if not request.allow_write or not request.allow_delete:
            raise KaggleRuntimeError(
                "policy",
                "Delete operations require --allow-write and --allow-delete",
            )
        resource = _extract_delete_resource(request.arguments)
        if not resource or request.confirm_resource != resource:
            raise KaggleRuntimeError(
                "policy",
                "Delete confirmation must exactly match the target resource",
                details={
                    "resource": resource,
                    "confirmed": request.confirm_resource,
                },
            )
    return operation

from __future__ import annotations

import os
import re
from collections.abc import Sequence
from pathlib import Path
from typing import Union

from .result import KaggleRuntimeError


REDACTED = "[REDACTED]"

_ENV_SECRET = re.compile(
    r"(?i)\b((?:KAGGLE_(?:API_TOKEN|KEY|USERNAME)|ACCESS_TOKEN|TOKEN)"
    r"\s*=\s*)([^\s,;'\"\\]+)"
)
_BEARER = re.compile(
    r"(?i)(Authorization\s*:\s*Bearer\s+)([^\s,;'\"\\]+)"
)
_TOKEN_ARGUMENT = re.compile(
    r"(?i)(--?(?:api[-_]?token|token|key)(?:=|\s+))"
    r"([^\s,;'\"\\]+)"
)
_SIGNED_QUERY = re.compile(
    r"(?i)([?&](?:X-Goog-Signature|X-Amz-Signature|Signature|"
    r"Access_Token|Token)=)([^&#\s'\"\\]+)"
)
_KGAT_TOKEN = re.compile(r"\bKGAT_[A-Za-z0-9_-]+\b")
_CONTROL_CHARACTERS = re.compile(r"[\x00-\x1f\x7f]")
_INLINE_CREDENTIAL_FLAGS = frozenset(
    {"--api-token", "--header", "--token"}
)


def redact_text(text: str) -> str:
    value = str(text)
    value = _ENV_SECRET.sub(lambda match: match.group(1) + REDACTED, value)
    value = _BEARER.sub(lambda match: match.group(1) + REDACTED, value)
    value = _TOKEN_ARGUMENT.sub(lambda match: match.group(1) + REDACTED, value)
    value = _SIGNED_QUERY.sub(lambda match: match.group(1) + REDACTED, value)
    value = _KGAT_TOKEN.sub(REDACTED, value)
    return value


def redact_arguments(arguments: Sequence[str]) -> tuple[str, ...]:
    return tuple(redact_text(str(argument)) for argument in arguments)


def contains_inline_credential(arguments: Sequence[str]) -> bool:
    for index, argument in enumerate(arguments):
        value = str(argument)
        lowered = value.lower()
        if (
            "authorization:" in lowered
            or "kaggle_api_token" in lowered
            or "kaggle_key" in lowered
            or _KGAT_TOKEN.search(value)
        ):
            return True
        for flag in _INLINE_CREDENTIAL_FLAGS:
            if lowered == flag and index + 1 < len(arguments):
                return True
            if lowered.startswith(flag + "="):
                return True
    return False


def _reject_control_characters(value: str, *, label: str) -> None:
    if _CONTROL_CHARACTERS.search(value):
        raise KaggleRuntimeError(
            "path",
            f"{label} cannot contain control characters",
        )


def resolve_output_path(root: Path, candidate: Union[str, Path]) -> Path:
    root_path = Path(root)
    candidate_path = Path(candidate)
    _reject_control_characters(str(root_path), label="Output root")
    _reject_control_characters(str(candidate_path), label="Output path")

    resolved_root = root_path.resolve(strict=False)
    if candidate_path.is_absolute():
        resolved_candidate = candidate_path.resolve(strict=False)
    else:
        resolved_candidate = (resolved_root / candidate_path).resolve(strict=False)

    try:
        common = Path(os.path.commonpath([resolved_root, resolved_candidate]))
    except ValueError as exc:
        raise KaggleRuntimeError(
            "path",
            "Output path is on a different filesystem root",
        ) from exc

    if os.path.normcase(str(common)) != os.path.normcase(str(resolved_root)):
        raise KaggleRuntimeError(
            "path",
            "Output path must remain inside the approved output root",
            details={
                "root": str(resolved_root),
                "candidate": str(resolved_candidate),
            },
        )
    return resolved_candidate
